<?php require_once __DIR__.'/auth.php';require_admin();require_once __DIR__.'/../includes/admin_layout.php';$pdo=db();$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$old=(string)$_POST['old_password'];$new=(string)$_POST['new_password'];$st=$pdo->prepare('SELECT password_hash FROM admins WHERE id=?');$st->execute([(int)$_SESSION['admin_id']]);$a=$st->fetch();if(!$a||!password_verify($old,$a['password_hash']))$error='Current password is incorrect.';elseif(strlen($new)<10)$error='New password must be at least 10 characters.';else{$pdo->prepare('UPDATE admins SET password_hash=? WHERE id=?')->execute([password_hash($new,PASSWORD_DEFAULT),(int)$_SESSION['admin_id']]);audit('password_change','admin',(int)$_SESSION['admin_id']);flash('Password changed successfully.');redirect('settings.php');}}admin_header('Settings','settings.php');?><div class="card" style="max-width:600px"><h1>Security Settings</h1><p class="muted">Change your administrator password before using the system with real hospital data.</p><?php if($error):?><div class="flash"><?=e($error)?></div><?php endif;?><form method="post"><?=csrf_field()?><div class="field"><label>Current password</label><input type="password" name="old_password" required></div><div class="field" style="margin-top:12px"><label>New password</label><input type="password" name="new_password" minlength="10" required></div><button style="margin-top:14px">Change password</button></form></div><?php admin_footer();
